    static class TraceDataEncoder {
        public static TraceTransferBean encoderFromContextBean(TraceContext ctx) {
            if (ctx == null) {
                return null;
            }
            //build message trace of the transfering entity content bean
            TraceTransferBean transferBean = new TraceTransferBean();
            StringBuilder sb = new StringBuilder(256);
            switch (ctx.getTraceType()) {
                case Pub: {
                    TraceBean bean = ctx.getTraceBeans().get(0);
                    //append the content of context and traceBean to transferBean's TransData
                    sb.append(ctx.getTraceType()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(ctx.getTimeStamp()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(ctx.getRegionId()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(ctx.getGroupName()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getTopic()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getMsgId()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getTags()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getKeys()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getStoreHost()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getBodyLength()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(ctx.getCostTime()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getMsgType().ordinal()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getOffsetMsgId()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(ctx.isSuccess()).append(TraceConstants.CONTENT_SPLITOR)//
                        .append(bean.getClientHost()).append(TraceConstants.FIELD_SPLITOR);
                }
                break;
                case SubBefore: {
                    for (TraceBean bean : ctx.getTraceBeans()) {
                        sb.append(ctx.getTraceType()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getTimeStamp()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getRegionId()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getGroupName()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getRequestId()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(bean.getMsgId()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(bean.getRetryTimes()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(bean.getKeys()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(bean.getClientHost()).append(TraceConstants.FIELD_SPLITOR);//
                    }
                }
                break;
                case SubAfter: {
                    for (TraceBean bean : ctx.getTraceBeans()) {
                        sb.append(ctx.getTraceType()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getRequestId()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(bean.getMsgId()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getCostTime()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.isSuccess()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(bean.getKeys()).append(TraceConstants.CONTENT_SPLITOR)//
                            .append(ctx.getContextCode()).append(TraceConstants.CONTENT_SPLITOR)
                            .append(ctx.getTimeStamp()).append(TraceConstants.CONTENT_SPLITOR)
                            .append(ctx.getGroupName()).append(TraceConstants.FIELD_SPLITOR);

                    }
                }
                break;
                default:
            }
            transferBean.setTransData(sb.toString());
            for (TraceBean bean : ctx.getTraceBeans()) {

                transferBean.getTransKey().add(bean.getMsgId());
                if (bean.getKeys() != null && bean.getKeys().length() > 0) {
                    transferBean.getTransKey().add(bean.getKeys());
                }
            }
            return transferBean;
        }
    }

    @Test
    public void testEncoderFromContextBean() {
        // Setup TraceBean
        TraceBean bean = new TraceBean();
        bean.setTopic("testTopic");
        bean.setMsgId("msg-123");
        bean.setTags("testTag");
        bean.setKeys("key-456");
        bean.setStoreHost("localhost");
        bean.setBodyLength(1024);
        bean.setMsgType(MessageType.NORMAL);
        bean.setOffsetMsgId("offset-789");
        bean.setClientHost("clientHost");
        bean.setRetryTimes(3); // Set retryTimes

        // Setup TraceContext
        TraceContext ctx = new TraceContext();
        ctx.setTraceType(TraceType.Pub);
        ctx.setTimeStamp(1625077800000L);
        ctx.setRegionId("region-1");
        ctx.setGroupName("groupA");
        ctx.setCostTime(250);
        ctx.setSuccess(true);
        List<TraceBean> beans = new ArrayList<>();
        beans.add(bean);
        ctx.setTraceBeans(beans);

        // Encode TraceContext to TraceTransferBean
        TraceTransferBean transferBean = TraceDataEncoder.encoderFromContextBean(ctx);

        // Build expected transData string
        String expectedTransData = TraceType.Pub.toString() + TraceConstants.CONTENT_SPLITOR +
                                   ctx.getTimeStamp() + TraceConstants.CONTENT_SPLITOR +
                                   ctx.getRegionId() + TraceConstants.CONTENT_SPLITOR +
                                   ctx.getGroupName() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getTopic() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getMsgId() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getTags() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getKeys() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getStoreHost() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getBodyLength() + TraceConstants.CONTENT_SPLITOR +
                                   ctx.getCostTime() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getMsgType().ordinal() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getOffsetMsgId() + TraceConstants.CONTENT_SPLITOR +
                                   ctx.isSuccess() + TraceConstants.CONTENT_SPLITOR +
                                   bean.getClientHost() + TraceConstants.FIELD_SPLITOR;

        // Assertions
        Assert.assertEquals("TransData does not match expected value", expectedTransData, transferBean.getTransData());
        Assert.assertEquals("TransKey size should be 2", 2, transferBean.getTransKey().size());
        Assert.assertTrue("TransKey should contain msgId", transferBean.getTransKey().contains(bean.getMsgId()));
        Assert.assertTrue("TransKey should contain keys", transferBean.getTransKey().contains(bean.getKeys()));
    }
}

