public class NamespaceUtilTest {

    private static final String INSTANCE_ID = "MQ_INST_XXX";
    private static final String INSTANCE_ID_WRONG = "MQ_INST_XXX1";
    private static final String TOPIC = "TOPIC_XXX";
    private static final String GROUP_ID = "GID_XXX";
    private static final String SYSTEM_TOPIC = "rmq_sys_topic";
    private static final String GROUP_ID_WITH_NAMESPACE = INSTANCE_ID + NamespaceUtil.NAMESPACE_SEPARATOR + GROUP_ID;
    private static final String TOPIC_WITH_NAMESPACE = INSTANCE_ID + NamespaceUtil.NAMESPACE_SEPARATOR + TOPIC;
    private static final String RETRY_TOPIC = "RETRY_" + GROUP_ID;
    private static final String RETRY_TOPIC_WITH_NAMESPACE =
        "RETRY_" + INSTANCE_ID + NamespaceUtil.NAMESPACE_SEPARATOR + GROUP_ID;
    private static final String DLQ_TOPIC = "DLQ_" + GROUP_ID;
    private static final String DLQ_TOPIC_WITH_NAMESPACE =
        "DLQ_" + INSTANCE_ID + NamespaceUtil.NAMESPACE_SEPARATOR + GROUP_ID;

    @Test
    public void testWithoutNamespace() {
        // Test removing namespace from a topic with correct namespace
        String result = NamespaceUtil.withoutNamespace(TOPIC_WITH_NAMESPACE, INSTANCE_ID);
        Assert.assertEquals(TOPIC, result);

        // Test removing namespace from a group ID with correct namespace
        String resultGroup = NamespaceUtil.withoutNamespace(GROUP_ID_WITH_NAMESPACE, INSTANCE_ID);
        Assert.assertEquals(GROUP_ID, resultGroup);

        // Test namespace does not match
        String resultNoMatch = NamespaceUtil.withoutNamespace(TOPIC_WITH_NAMESPACE, INSTANCE_ID_WRONG);
        Assert.assertEquals(TOPIC_WITH_NAMESPACE, resultNoMatch);

        // Test input without namespace
        String resultNoNamespace = NamespaceUtil.withoutNamespace(TOPIC, INSTANCE_ID);
        Assert.assertEquals(TOPIC, resultNoNamespace);

        // Test retry topic with namespace
        String resultRetry = NamespaceUtil.withoutNamespace(RETRY_TOPIC_WITH_NAMESPACE, INSTANCE_ID);
        Assert.assertEquals(RETRY_TOPIC_WITH_NAMESPACE, resultRetry);

        // Test DLQ topic with namespace
        String resultDLQ = NamespaceUtil.withoutNamespace(DLQ_TOPIC_WITH_NAMESPACE, INSTANCE_ID);
        Assert.assertEquals(DLQ_TOPIC_WITH_NAMESPACE, resultDLQ);

        // Test system topic should not remove namespace if not applicable
        String resultSystem = NamespaceUtil.withoutNamespace(SYSTEM_TOPIC, INSTANCE_ID);
        Assert.assertEquals(SYSTEM_TOPIC, resultSystem);
    }

}

