        SubscriptionData subscriptionData = new SubscriptionData("TestTopic", "TestSub");

        // Initialize codeSet with 1, 2, 3
        Set<Integer> codeSet = new LinkedHashSet<>();
        codeSet.add(1);
        codeSet.add(2);
        codeSet.add(3);
        subscriptionData.setCodeSet(codeSet);

        // Initialize tagsSet with "TAGA", "TAGB", "TAG3"
        Set<String> tagsSet = new LinkedHashSet<>();
        tagsSet.add("TAGA");
        tagsSet.add("TAGB");
        tagsSet.add("TAG3");
        subscriptionData.setTagsSet(tagsSet);

        // Ensure all fields used in hashCode are set
        subscriptionData.setClassFilterMode(false);
        subscriptionData.setExpressionType("TAG");

        // Compute expected hashCode
        final int prime = 31;
        int result = 1;
        result = prime * result + (subscriptionData.isClassFilterMode() ? 1231 : 1237);
        result = prime * result + ((subscriptionData.getCodeSet() == null) ? 0 : subscriptionData.getCodeSet().hashCode());
        result = prime * result + ((subscriptionData.getSubString() == null) ? 0 : subscriptionData.getSubString().hashCode());
        result = prime * result + ((subscriptionData.getTagsSet() == null) ? 0 : subscriptionData.getTagsSet().hashCode());
        result = prime * result + ((subscriptionData.getTopic() == null) ? 0 : subscriptionData.getTopic().hashCode());
        result = prime * result + ((subscriptionData.getExpressionType() == null) ? 0 : subscriptionData.getExpressionType().hashCode());

        int expectedHashCode = result;

        // Assert that hashCode does not match the identity hash code
        Assert.assertNotEquals(System.identityHashCode(subscriptionData), subscriptionData.hashCode());

        // Assert that the custom hashCode is correct
        Assert.assertEquals(expectedHashCode, subscriptionData.hashCode());
    }
