import static org.assertj.core.api.Assertions.assertThat;

public class MessageClientIDSetterTest {

    @Test
    public void testGetIPStrFromID() throws Exception {
        // Access the private method createUniqIDBuffer using reflection
        Method method = MessageClientIDSetter.class.getDeclaredMethod("createUniqIDBuffer");
        method.setAccessible(true);

        // Test with IPv4 address
        byte[] uniqIDBufferIPv4 = (byte[]) method.invoke(null);
        // Ensure the buffer has enough space for IPv4 (4 bytes)
        if (uniqIDBufferIPv4.length < 4) {
            throw new IllegalArgumentException("Buffer size is too small for IPv4 address.");
        }
        String expectedIPv4 = "192.168.1.1";
        byte[] ipv4Bytes = new byte[] {(byte)192, (byte)168, 1, 1};
        System.arraycopy(ipv4Bytes, 0, uniqIDBufferIPv4, 0, ipv4Bytes.length);
        String msgIDIPv4 = bytesToHex(uniqIDBufferIPv4);
        String ipStrIPv4 = MessageClientIDSetter.getIPStrFromID(msgIDIPv4);
        assertThat(ipStrIPv4).isEqualTo(expectedIPv4);

        // Test with IPv6 address
        // Instead of using createUniqIDBuffer, create a buffer with sufficient size for IPv6
        byte[] uniqIDBufferIPv6 = new byte[16];
        String expectedIPv6 = "2001:0db8:85a3:0000:0000:8a2e:0370:7334";
        byte[] ipv6Bytes = new byte[] {
            (byte)0x20, (byte)0x01, (byte)0x0d, (byte)0xb8,
            (byte)0x85, (byte)0xa3, (byte)0x00, (byte)0x00,
            (byte)0x00, (byte)0x00, (byte)0x8a, (byte)0x2e,
            (byte)0x03, (byte)0x70, (byte)0x73, (byte)0x34
        };
        System.arraycopy(ipv6Bytes, 0, uniqIDBufferIPv6, 0, ipv6Bytes.length);
        String msgIDIPv6 = bytesToHex(uniqIDBufferIPv6);
        String ipStrIPv6 = MessageClientIDSetter.getIPStrFromID(msgIDIPv6);
        assertThat(ipStrIPv6).isEqualTo(expectedIPv6);
    }

    // Helper method to convert byte array to hex string
    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for(byte b : bytes){
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

