    public void testGetPidFromID() {
        // Mocked PID for testing
        int mockedPid = 12345;

        // Create a unique ID with the mocked PID
        String uniqID = createUniqIDWithPid(mockedPid);

        // Extract PID from the unique ID
        int pidFromID = MessageClientIDSetter.getPidFromID(uniqID);

        // Assert that the extracted PID matches the mocked PID
        assertThat(pidFromID).isEqualTo(mockedPid);
    }

    /**
     * Helper method to create a unique ID string with a specific PID.
     */
    private String createUniqIDWithPid(int pid) {
        ByteBuffer buffer = ByteBuffer.allocate(16); // Total 16 bytes
        buffer.putInt(0); // First 4 bytes (indices 0-3)
        buffer.putShort((short) pid); // PID at bytes 4-5
        buffer.putLong(System.currentTimeMillis()); // Next 8 bytes (indices 6-13)
        buffer.putShort((short) 0); // Last 2 bytes (indices 14-15)
        return UtilAll.bytes2string(buffer.array());
    }
}

